// Find All Duplicates: значения 1..n, пометка знаком, O(1) доп. памяти
var dups = new List<int>();
foreach (int x in a) {
    int v = Math.Abs(x);                 // ячейку могли пометить раньше
    if (a[v - 1] < 0) dups.Add(v);       // уже помечена — повтор
    else a[v - 1] = -a[v - 1];
}

